function reductionMerge(){
 if(sim.stage>2||sim.items.length<=1||sim.selection.length!==2)return;
 let chosen=sim.selection.map(id=>sim.items.find(x=>x.id===id));if(chosen.some(x=>!x)){sim.selection=[];return;}
 if(sim.stage===0&&sim.merges.length===0&&!reductionPairsEqual(chosen.map(x=>x.value).sort((a,b)=>a-b),[6,9])){toast('For Plan A, start with 6 and 9 as instructed.');return;}
 const a=chosen[0].value,b=chosen[1].value,sum=a+b;
 sim.items=sim.items.filter(x=>!sim.selection.includes(x.id));sim.items.push({id:sim.nextId++,value:sum});sim.items.sort((a,b)=>a.value-b.value||a.id-b.id);
 sim.total+=sum;sim.merges.push({a,b,sum,total:sim.total});sim.selection=[];sim.feedback='';sim.ready=false;persistReduction();rerenderPractice();
}
