el('saveBtn').onclick=exportJSON;el('importBtn').onclick=()=>fileInput.click();fileInput.onchange=()=>importJSON(fileInput.files?.[0]);el('teacherBtn').onclick=()=>{if(!state){toast('Start as a student first.');return;}if(teacherAuthorized){if(idx===-1){render();document.querySelector('.teacher-tools')?.scrollIntoView({behavior:'smooth'});}else document.querySelector('.teacher-tools')?.scrollIntoView({behavior:'smooth'});}else teacherLogin();};
